package com.reqlens.app;
import android.app.*;import android.content.*;import android.graphics.Typeface;import android.os.Bundle;import android.view.*;import android.widget.*;
public final class ToolsActivity extends Activity{
 @Override public void onCreate(Bundle b){super.onCreate(b);LinearLayout r=new LinearLayout(this);r.setOrientation(LinearLayout.VERTICAL);r.setPadding(20,20,20,20);TextView t=new TextView(this);t.setText("ReqLens Tools");t.setTextSize(24);t.setTypeface(Typeface.DEFAULT_BOLD);r.addView(t);r.addView(btn("Research Suite — 80 capabilities",ResearchSuiteActivity.class));r.addView(btn("Evidence Vault",EvidenceVaultActivity.class));r.addView(btn("Decoder / Encoder",DecoderActivity.class));r.addView(btn("Comparer",ComparerActivity.class));r.addView(btn("Rules",RulesActivity.class));r.addView(btn("Variations",IntruderActivity.class));r.addView(btn("WebSocket History",WebSocketHistoryActivity.class));r.addView(btn("Traffic Map",TrafficMapActivity.class));r.addView(btn("Host / Endpoint Summary",HostSummaryActivity.class));r.addView(btn("Project Comparison",ProjectCompareActivity.class));r.addView(btn("Diagnostics",DiagnosticsActivity.class));r.addView(btn("Settings",SettingsActivity.class));setContentView(r);}
 private Button btn(String s,Class<?>c){Button b=new Button(this);b.setText(s);b.setOnClickListener(v->startActivity(new Intent(this,c)));return b;}
}
